const src = ($json.body && typeof $json.body === 'object') ? $json.body : $json;
const g = k => (src[k] !== undefined && src[k] !== null) ? src[k] : '';
const prefDate = g('Preferred Date') || g('preferredDate');
const prefTime = g('Preferred Time') || g('preferredTime');
const preferredTime = [prefDate, prefTime].filter(Boolean).join(' ');
return [{ json: {
  source: 'Website Form',
  firstName: g('First Name') || g('firstName'),
  lastName: g('Last Name') || g('lastName'),
  phone: g('Phone') || g('phone'),
  email: g('Email') || g('email'),
  address: g('Address') || g('address'),
  serviceNeeded: g('Service Needed') || g('serviceNeeded'),
  description: g('Description') || g('description'),
  photosLink: g('Photos Link') || g('photosLink'),
  preferredTime,
  status: 'New',
  logChannel: 'Website Form',
  logDirection: 'Inbound',
  logHandler: 'System',
  logSummary: 'New lead submitted via website form',
  logNotes: ''
}}];

const lead = $('Normalize Lead').first().json;
const leadId = $json.leadId || '';
const systemPrompt = 'You write the instant confirmation text message a roofing company sends a customer right after they submit the website inspection-request form.\n' +
  'Rules:\n' +
  '- Warm, friendly, professional. Sound like a local Boston-area roofer, not a robot.\n' +
  '- Under 320 characters. One short paragraph.\n' +
  '- Greet them by first name if one is available.\n' +
  '- Confirm we received their request and reference their service need if it helps.\n' +
  '- Tell them a team member will reach out shortly to schedule their free inspection.\n' +
  '- No emojis. No links. Do not promise a specific price or appointment time.';
const schema = { type: 'object', additionalProperties: false, properties: { message: { type: 'string' } }, required: ['message'] };
const userContent = JSON.stringify({ firstName: lead.firstName, serviceNeeded: lead.serviceNeeded, company: 'Valfin Tech' });
return [{ json: { ...lead, leadId, systemPrompt, schema, userContent } }];

const resp = $json;
let txt = '';
if (Array.isArray(resp.content)) { const t = resp.content.find(b => b.type === 'text'); txt = t ? t.text : ''; }
let msg = '';
try { msg = (JSON.parse(txt).message) || ''; } catch (e) { msg = txt || ''; }
const lead = $('Build Confirmation Request').first().json;
return [{ json: { ...lead, smsMessage: msg } }];

const lead = $('Normalize Lead').first().json;
const crm = $json;
return [{ json: {
  source: lead.source || '',
  firstName: lead.firstName || '',
  lastName: lead.lastName || '',
  phone: lead.phone || '',
  email: lead.email || '',
  address: lead.address || '',
  serviceNeeded: lead.serviceNeeded || '',
  description: lead.description || '',
  preferredTime: lead.preferredTime || '',
  leadId: crm.leadId || '',
  dateCreated: crm.dateCreated || '',
  status: crm.status || 'New'
}}];
